import com.github.javaparser.symbolsolver.javaparsermodel.JavaParserFacade;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;
import com.github.javaparser.JavaSymbolSolver;
import com.github.javaparser.resolution.declarations.ResolvedMethodDeclaration;

public class TBTest {
  public static void main(String[] a) {
    JavaSymbolSolver s = new JavaSymbolSolver(new ReflectionTypeSolver(false));
    JavaParser.getStaticConfiguration().setSymbolResolver(s);
    String code = "public class X { public static void main(String[] args) { \"a\".formatted(\"b\"); \"\"\"\n Hello %s! \n\"\"\".formatted(\"w\"); } }";
    CompilationUnit cu = new JavaParser().parse(code).getResult().get();
    for (MethodCallExpr n : cu.findAll(MethodCallExpr.class)) {
      ResolvedMethodDeclaration r = JavaParserFacade.get(new ReflectionTypeSolver(false)).solve(n).getCorrespondingDeclaration();
      System.out.println("SOLVED: " + n.getName() + " as " + r.getQualifiedSignature());
    }
  }
}
EOF
